package app

import "github.com/gin-gonic/gin"

func modelScriptContract(locale ...string) gin.H {
    english := len(locale) > 0 && locale[0] == "en-US"
    choose := func(zh, en string) string { if english { return en }; return zh }
    return gin.H{
        "version": 7,
        "package": choose("script.json: schemaVersion/name/capability/description/entry/inputs/phases/features/auth。默认 entry=adapter.js、inputs=inputs.json。阶段为具名 async 函数导出，支持包内 JS/JSON 相对 import。", "script.json declares schemaVersion/name/capability/description/entry/inputs/phases/features/auth. Defaults: adapter.js and inputs.json. Export named async phase functions; relative JS/JSON imports stay inside the package."),
        "runtime": choose("脚本在服务端隔离执行，返回请求或结果对象；不使用浏览器 File/Blob/FormData、fetch、npm、文件系统或进程。密钥由服务端注入，不提供 apiKey。脚本初始化、请求准备、结果和单个流式事件各有时限，与供应商等待时限独立。运行边界由站点管理控制，通过 admin_site_get 读取，不在脚本包中声明。", "Scripts run in the server sandbox and return request or result objects. No browser File/Blob/FormData, fetch, npm, filesystem or processes. The server injects credentials; apiKey is not exposed. Sandbox initialization, request preparation, results, and each stream event have separate limits from provider waits. Runtime limits come from Site management (admin_site_get), not the script package."),
        "input": gin.H{
            "model": choose("供应商模型 ID，不包含渠道前缀", "Provider model ID without channel prefix"),
            "prompt": choose("提示词或 TTS 待朗读文本，不自动把系统提示词混入朗读正文", "Prompt or TTS input text; system instructions are not appended to spoken content"),
            "messages": choose("完整文本消息及工具结果，素材块使用 image_asset 与 assetId", "Conversation and tool results; image_asset blocks reference assetId"),
            "params": choose("脚本输入定义与本次、管理员模型及脚本默认值合并并校验后的参数", "Declared inputs resolved from explicit values, administrator model defaults and script defaults"),
            "images/videos/audios": choose("分类素材数组：assetId/role/transport/mimeType/bytes/width/height/durationMs/fps/videoCodec/audioCodec/voiceId；仅命名 asset 控件提供 parameterKey，reference 按角色和顺序读取，不是 params 数组。https 在提交时提供 url，data 提供 dataUrl，file 由 multipart 里的 assetId 流式读取。校验与预览阶段不签发地址。", "Media arrays with assetId/role/transport/mimeType/bytes/width/height/durationMs/fps/videoCodec/audioCodec/voiceId. Only named asset controls provide parameterKey; reference controls use ordered role arrays, not params arrays. https resolves to url, data to dataUrl, file uses multipart assetId. Validation and preview do not issue signed URLs."),
            "tools": choose("Agent 本轮允许的 OpenAI function tools。脚本只转换定义与结果，不执行业务工具。", "Allowed OpenAI function tools for this Agent request. Scripts adapt definitions and calls; application code executes tools."),
            "upstreamId": choose("平台保存的供应商任务编号，查询与取消时提供", "Persisted provider job ID for query and cancel"),
            "previousResult": choose("后续只读请求期间保留前一结果的 usage / usageState / progress，随响应持久保存；result 阶段可将其带入最终结果", "Previous normalized usage / usageState / progress during read-only follow-ups, persisted with the response; result can carry these into the final output"),
        },
        "phases": gin.H{
            "validate": "optional: standard input -> {valid:true} or {valid:false,error}",
            "submit": "required: standard input -> request descriptor",
            "query": "optional asynchronous jobs: standard input with upstreamId -> ONE query request; platform schedules polling",
            "stream": "optional SSE: {event,state,input} -> cumulative state {text,reasoning,toolCalls,usage,responseItems,progress,complete,status}; reasoning is only provider-returned readable text or summaries (not encrypted items); progress is an optional provider-reported number in [0,100]; complete=true only after a real protocol terminal event",
            "result": "required: {response,phase,input} -> normalized result or {request:{method:'GET',path:...}} for a read-only follow-up",
            "usage": "optional: {response,input} -> usage measurements; omit unknown values",
            "cancel": "optional: standard input with upstreamId -> cancel request; do not delete the evidence needed to query results",
        },
        "request": gin.H{"method":"GET/POST/PUT/PATCH/DELETE", "path": choose("相对实际 API Base URL，不自动补 /v1。/ 开头从域名根路径解析。生成请求须保持渠道 origin。", "Relative to the actual API Base URL, with no implicit /v1. Leading / resolves from the origin root. Generation requests must stay on the channel origin."), "headers":"optional non-secret string headers; authentication and transport headers are server-managed", "body":"JSON object or raw text", "form":"URL-encoded object, mutually exclusive with body/multipart", "multipart":"[{name,value} or {name,assetId}] — platform streams the original and sets the boundary", "responseType":"json | sse | binary | image-json; binary/image-json require a durable generation task and return responseFile"},
        "result": gin.H{"status":"queued/running/completed/incomplete/failed/cancelled/confirmation_required", "upstreamId":"required while queued/running; normalize the actual submit response ID (e.g. task_id vs task.id) and declare query; never guess an ID or resubmit", "progress":"optional provider-reported number from 0 to 100; convert only documented units, omit when unavailable; 100 does not mean the original is saved", "text":"text output", "url":"HTTPS media output, saved by the platform", "outputs":"[{url} or {b64_json}]", "responseFile":"pass through response.responseFile only", "mimeType":"original MIME type, including audio/pcm when applicable", "toolCalls":"[{id,type:'function',function:{name,arguments:'JSON string'}}]", "usage":"input_tokens/cached_tokens/output_tokens/images/seconds/characters/requests; input_tokens includes cache", "usageState":"actual/estimated/unknown", "error":"visible error; preserve partial outputs and usage"},
        "inputs": choose("控件 key/label/labelEn/type/required/default/description/descriptionEn。type: text/textarea/number/switch/select/asset/reference；options=[{label,labelEn,value}] 为限定选项，适用于 select/text/textarea/number，值须符合字段类型。文本或数字可定义 suggestions 建议值，允许自定义输入，不扩大其他约束；模型 options 可将其收窄为限定选项。number: min/max/step；文本: minLength/maxLength；素材: role=image/video/audio、transport=https/file/data、minCount/maxCount、mimeTypes/maxBytes、尺寸和时长范围。when:{key,values} 引用无条件普通参数，条件成立时显示并校验。模型覆盖只能修改显示、默认值与缩小范围。", "Controls use key/label/labelEn/type/required/default/description/descriptionEn. Types: text/textarea/number/switch/select/asset/reference. options=[{label,labelEn,value}] restricts select/text/textarea/number values and preserves field types. Text and numeric suggestions allow custom input within other constraints; model options can narrow these to an allowed list. Numeric/text/media constraints are declarative. when:{key,values} references an unconditional scalar input and controls display plus validation. Model overrides only change presentation, defaults or narrow allowed values."),
        "mediaAuthoring": gin.H{
            "modes": choose("按真实文档列出每种创作模式、所需素材和参数映射，新建视频脚本优先声明无条件 mode select；只提供真实支持的文生、图生、首尾帧或参考模式，不能按模型名称补造。选项值由 adapter 映射上游，并不要求供应商存在同名 mode 字段。生图可在接口支持时按 images 是否为空选择生成 / 编辑路径。", "Derive each creation mode, media requirements and parameter mapping from actual API docs. Prefer an unconditional mode select for new video scripts. Declare only supported text, image, keyframe or reference modes; do not infer them from model names. The adapter maps option values to provider requests; a provider mode field is not required. Image scripts may choose generation or editing by the presence of images when the API supports this."),
            "conditions": choose("when 仅引用一个无条件普通字段，不支持嵌套条件或选项级条件；不适用的普通参数不传入脚本。同一角色同时最多一个 reference 控件，模式间用互斥 when。单个命名素材用 asset；命名匹配优先，不重复计入 reference。精确声明数量、MIME、字节、尺寸与毫秒时长；跨字段组合、帧顺序、混用和总量限制在 validate 校验，不能只靠网页筛选或静默改值。", "when references one unconditional scalar field; nested and per-option conditions are unsupported. Inactive scalar inputs are omitted. Allow at most one active reference control per role, using disjoint mode conditions. Use asset for a named single slot; named matches take precedence and are excluded from reference counts. Declare counts, MIME, bytes, dimensions and durations in milliseconds. Validate combinations, frame ordering, mixing and aggregate limits in validate rather than relying on UI filtering or silently changing values."),
            "parameters": choose("图片 count 是单次返回张数，支持时默认 1，按文档设限定选项或 min/max/step，不新增批量请求次数或循环提交。有限选项用 select/options，可自定义才用 text/number 加 suggestions，保留数值与布尔类型。比例、像素尺寸、分辨率和时长单位分别映射；不复制其他供应商的默认值或边界。label/labelEn 简短，说明写 description/descriptionEn 供参数提示；核心参数保持可见，次要项才设 advanced。", "Image count is outputs per request, defaulting to 1 when supported, with documented options or min/max/step; do not add batch request counts or submission loops. Use select/options for finite values, and text/number with suggestions for custom input, preserving numeric and boolean types. Map aspect ratios, pixel sizes, resolution tiers and duration units separately. Do not copy another provider's defaults or limits. Keep label/labelEn short, use description/descriptionEn for parameter help, and reserve advanced for secondary controls."),
        },
        "workbench": gin.H{
            "videoModes": choose("工作台优先使用真实 mode。无 mode、存在含 none 且仅使用 none/first/last/both 的可见 keyframe select，且 none 时有生效的图片 reference 定义时，界面可将 none 分成参考与可选的文生入口；文生要求所有生效参考均可省略，全能参考要求同时声明图片、视频、音频。界面 workbench_mode 不进入脚本或上游，两种 none 入口仍传 keyframe=none，区别是素材；first/last/both 保留原值。已有脚本字段不为界面自动重命名或升级。", "The workbench prefers a real mode input. Without mode, a visible keyframe select containing none and only none/first/last/both values plus image references active under none can expose reference and optional text entries for none. Text requires all active references to be optional; multimodal references require image, video and audio definitions. UI-only workbench_mode never enters scripts or provider requests: both none entries submit keyframe=none with different media, while first/last/both retain their values. Existing script fields are not automatically renamed or upgraded for the UI."),
            "presentation": choose("模型位于参考素材下方，模式位于模型下方，其余参数两列展示。count/seconds/duration 的有限 min/max/step 可生成下拉项，description/descriptionEn 与约束用于标题提示。历史封面的 4:3 裁切仅影响显示，不限制生成比例或处理原件。当前用户创作草稿自动保存，不修改共享默认值；记录删除、手动加入资产库与当前浏览器下载由应用负责，脚本只返回规范结果。", "Models appear below reference media, modes below models, and other parameters in two columns. Finite min/max/step ranges for count/seconds/duration can populate selects; descriptions and constraints supply title help. History covers are cropped to 4:3 for display only, without constraining generation or processing originals. Current user drafts auto-save without changing shared defaults. The application handles record deletion, manual library retention and downloads in the current browser; scripts only return normalized results."),
        },
        "builtinMedia": choose("以下仅描述对应内置脚本，自建脚本的能力与默认值须独立核实。图片参数 size/resolution/quality/count/background：默认 1:1、1k、auto、1、默认不透明；size 支持参考比例、auto 和自定义像素，脚本映射为 size 与 n。视频参数 mode/seconds/size/resolution/generateAudio/watermark：默认 frames、6、1:1、720p、true、false；脚本映射 /videos multipart。音频仅内置 OpenAI TTS：voice/format/speed/instructions，默认 alloy/mp3/1/无指令，映射 audio/speech 的 voice/response_format/speed/instructions，不接受参考音频或旧参数别名。", "These defaults describe the corresponding builtin adapters only; verify capabilities and defaults independently for custom scripts. Image inputs size/resolution/quality/count/background default to 1:1, 1k, auto, 1 and opaque. The script converts reference ratios, auto or custom pixels to size and maps count to n. Video inputs mode/seconds/size/resolution/generateAudio/watermark default to frames, 6, 1:1, 720p, true and false, mapped to /videos multipart. The only builtin audio adapter is OpenAI TTS: voice/format/speed/instructions default to alloy/mp3/1/no instructions, mapped to audio/speech voice/response_format/speed/instructions; no reference audio or legacy parameter aliases."),
        "auth": "script.json auth.type=bearer (default), header with header/prefix, or none. Credentials stay server-side. sign(value) provides HMAC-SHA256 hex; encode(kind,value) supports base64/hex/url/sha256.",
        "preview": choose("包检查只编译与校验定义，不需要真实调用；样例映射使用已确认运行边界，按用户归属读取资产元数据，HTTPS 使用 preview.invalid 占位地址，data 不读取原件。不会签发素材地址、联网或注入凭据，不能作为真实可用证据。", "Package checks compile and validate definitions without provider calls. Sample mapping uses confirmed execution limits and owner-checked asset metadata, with preview.invalid HTTPS placeholders and no original data. It issues no private URLs, network requests or credentials and does not prove API availability."),
        "lifecycle": choose("内置只读且不可复制、删除；自建草稿按 revision 保存，可不付费测试就发布。管理员可明确确认后按脚本记录 version 删除无渠道模型引用的自建脚本、草稿与发布版本，已有任务快照、资产和用量保留。模型固定发布版本，任务固定脚本、参数和价格。助手可编写草稿与读取脱敏记录，真实测试、发布及删除由管理员主动执行。", "Builtins are immutable and cannot be copied or deleted. Custom drafts use revision checks; publishing does not require paid testing. Administrators may explicitly delete an unreferenced custom script, its draft and versions using the script record version; existing task snapshots, assets and usage remain. Models pin published versions and tasks pin code, inputs and prices. The assistant writes drafts and reads redacted evidence; administrators actively test, publish and delete."),
        "authoringSkill": "model-api-adapter",
    }
}

func (a *App) getModelScriptContract(c *gin.Context) { c.JSON(200, modelScriptContract(c.Query("locale"))) }
